const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function sourceStatus(s,{backend=false,uncertain=false}={}){return `<section class="source-status" aria-label="Case information sources"><div class="source-heading"><strong>Case information sources</strong><span>${uncertain?'Last loaded records · refresh required':backend?'Read through the server':'Browser simulation'}</span></div><div class="source-grid">${['payment','access'].map(key=>{const source=s.sources?.[key];const unavailable=source?.status==='unavailable',label=uncertain?'Status unconfirmed':unavailable?'Unavailable':source?'Record retrieved':backend?'Not refreshed yet':'Sample record';return `<div class="source-item ${unavailable||uncertain?'source-warning':''}"><span class="source-dot"></span><div><strong>${key==='payment'?'Payment system':'Course access system'}</strong><span>${label}</span><small>${source?.checkedAt?'Last attempt: '+esc(new Date(source.checkedAt).toLocaleTimeString()):backend?'Refresh to check this source.':'No external system contacted.'}</small>${unavailable?'<p>Current information could not be retrieved. Shown values may be out of date; this does not mean access is missing.</p>':''}</div></div>`}).join('')}</div>${s.sources&&Object.values(s.sources).some(x=>x.status==='unavailable')?'<p class="source-explanation">A source is unavailable. Approval and correction are on hold until both records can be checked.</p><button class="button" data-action="refresh">Retry source checks</button>':''}${s.job?.error?`<p role="alert" class="source-explanation">Workflow stopped: ${esc(s.job.error)}. Refresh the case before choosing the next step.</p>`:''}</section>`;}
